-- =====================================================================
-- Master data: Bhutan's 20 dzongkhags, 216 gewogs and thromdes, and
-- 4499 villages, for addresses (e.g. a gym member's registration).
--
-- From the BRECSA service's tbl_dzongkhag, tbl_gewog and tbl_chiwog (its
-- village list; its tbl_village has broken gewog links and isn't used).
-- Cleaned on the way in:
--   * 'Chukha' and 'Samdrupjongkhar' spelled Chhukha and Samdrup Jongkhar,
--     as the rest of SportsHub spells them; Paro's 'Throm' is 'Paro Throm'.
--   * Dropped: 227 'Unknown' placeholders and 7 rows whose gewog doesn't
--     exist (test rows and 'Abroad').
--   * Six Thimphu city localities whose gewog was missing (Babesa,
--     Changangkha, Changzamtok, Olakha, Zilukha, Dechecholing) belong to
--     Thim Throm: their codes fill the gaps in its sequence.
--
-- Ids are the source's, so records can be matched with it. Safe to re-run:
-- rows already here (even if renamed since) are left alone. Admins keep the
-- lists up to date under Admin -> Master data.
-- =====================================================================

